"""Migrated Meridian CRM 4.2 case_lifecycle workflow transitions."""

from typing import Any


def _value(record: dict, field: str) -> Any:
    """Return a legacy field value, treating missing fields as empty strings."""
    return record.get(field, "")


def _nonempty(record: dict, field: str) -> bool:
    value = _value(record, field)
    return value is not None and value != ""


def _nvl_severity(record: dict) -> str:
    value = _value(record, "SEV_CD")
    return "3" if value is None or value == "" else value


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one explicit case_lifecycle workflow event."""
    updated = dict(record)

    # Transitions are evaluated in legacy XML document order.
    if state == "N" and event == "assign" and _nonempty(updated, "OWNER_UID"):
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ASSIGN"],
            "notifies": [],
            "matched": True,
        }

    if state == "N" and event == "auto_escalate":
        updated["ESC_FLG"] = "Y"
        updated["SEV_CD"] = _nvl_severity(updated)
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    if (
        state == "A"
        and event == "auto_escalate"
        and _value(updated, "ESC_FLG") != "Y"
    ):
        updated["ESC_FLG"] = "Y"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_ESC"],
            "notifies": ["escalation"],
            "matched": True,
        }

    if state == "A" and event == "await_customer":
        return {
            "state": "P",
            "record": updated,
            "audits": ["CASE_PEND"],
            "notifies": [],
            "matched": True,
        }

    if state == "P" and event == "customer_reply":
        return {
            "state": "A",
            "record": updated,
            "audits": [],
            "notifies": [],
            "matched": True,
        }

    if (
        state == "A"
        and event == "resolve"
        and _value(updated, "RES_DT") != "00000000"
    ):
        return {
            "state": "R",
            "record": updated,
            "audits": ["CASE_RES"],
            "notifies": [],
            "matched": True,
        }

    if state == "R" and event == "close":
        return {
            "state": "X",
            "record": updated,
            "audits": ["CASE_CLOSE"],
            "notifies": [],
            "matched": True,
        }

    if state == "R" and event == "reopen":
        updated["RES_DT"] = "00000000"
        return {
            "state": "A",
            "record": updated,
            "audits": ["CASE_REOPEN"],
            "notifies": [],
            "matched": True,
        }

    return {
        "state": state,
        "record": updated,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
